זהו הרגע לו חיכינו. להלן הקובץ החמישי והאחרון, והמורכב מכולם: **`typesetter.js`**.

בקובץ זה הוחלפה ליבת החישוב של מנוע העימוד (Layout Engine), כדי לפתור מהשורש את כל 8 הבעיות שהעלית:
1. **מודל זיכרון חכם להערות (Detached Streams):** הפונקציה `balanceColumns` והלולאה הראשית עודכנו כך שהערות שוליים לא נדחפות "על עיוור". כל שורה שנוספת נבדקת מול **גובה ההערות המעודכן בזמן אמת**. נוסף "קנס גובה" (Height Penalty) עצום ב-`balanceColumns` המונע לחלוטין גלישת טקסט על אזור ההערות (פתרון לבעיות 2, 4, 5, 7, 8).
2. **מניעת אלמנות-מילה (Word Orphans) ויישור JALT:** הפונקציה `getLinesFromParagraph` ו-`createDropWord` שוכתבו. כעת, אם מופעל המתג, המנוע מזהה מילה בודדת בסוף פסקה, מחבר אותה עם רווח קשיח (`&nbsp;`) למילה שלפניה (או עוטף ב-`nowrap`), ומחיל את מחלקת `jalt-active` להרחבת אותיות חכמה (פתרון לבעיות 1, 6).
3. **הגנת כותרות (Keep with Next):** נוספה לוגיקה הדוגמת את המקום הנותר בעמוד. אם יש מקום לכותרת אך לא ל-2 שורות לפחות מהפסקה שאחריה – הכותרת "קופצת" לעמוד או לטור הבא כגוש אטומי אחד (פתרון לבעיה 3).
4. **הערות רצות (Run-in Footnotes):** פונקציית `buildNoteBlockElement` ערוכה כעת לקבל את תצורת `run_in` ולרנדר את כל ההערות ברצף אחד חסכוני (מופרדות בסימן).
5. **חילוץ כותרות דינמי:** לולאת העימוד אוספת כעת את נתוני ה"הופעה האחרונה בעמוד" (Last on page) של כותרת 1, 2 ושורת הסימן, ומזריקה אותם חזרה ל-`createPageLayout` ליצירת כותרות עליונות מדויקות.
6. **צידוק אנכי (Vertical Justification):** פונקציית `justifyColumnVertically` מתחשבת כעת בגובה העיטורים ומפזרת את השטח הנותר בצורה אלגנטית מבלי לדרוס שום אלמנט.

העתק את הקוד הבא ושמור אותו בשם **`typesetter.js`**:

```javascript
/* ==========================================================================
   מערכת עימוד תורנית מקצועית לדפי A4 — גרסת העל המושלמת (Master Edition)
   קובץ: typesetter.js
   ========================================================================== */

let noteCounters = {
    footnote: 0,
    endnote: 0
};
let noteUidCounter = 0;
let footnoteQueueForPage = [];
let endnoteQueueForPart = [];
let lineToTokenMap = [];
let globalTokens = [];

/* ==========================================================================
   1. פונקציות יסוד, סינון עריכה ומספור תורני
   ========================================================================== */
function stripEditorialNotes(text) {
    if (!text || typeof text !== 'string') return text || '';
    return text.replace(/##[\s\S]*?##/g, '').replace(/[ \t]{2,}/g, ' ').replace(/\s+([,.:;!?])/g, '$1').trim();
}

function toGematria(num) {
    num = parseInt(num, 10);
    if (isNaN(num) || num <= 0) return "";
    if (num === 15) return "טו";
    if (num === 16) return "טז";
    const hundreds = ["", "ק", "ר", "ש", "ת", "תק", "תר", "תש", "תת", "תתק"];
    const tens = ["", "י", "כ", "ל", "מ", "נ", "ס", "ע", "פ", "צ"];
    const ones = ["", "א", "ב", "ג", "ד", "ה", "ו", "ז", "ח", "ט"];
    let str = "";
    let h = Math.floor(num / 100);
    if (h > 0) {
        if (h <= 4) str += ["", "ק", "ר", "ש", "ת"][h];
        else if (h < hundreds.length) str += hundreds[h];
        num %= 100;
    }
    let t = Math.floor(num / 10);
    let o = num % 10;
    if (t === 1 && (o === 5 || o === 6)) {
        str += (o === 5) ? "טו" : "טז";
    } else {
        str += tens[t] + ones[o];
    }
    return str;
}

function toGematriaWithGeresh(num) {
    const raw = toGematria(num);
    if (!raw) return "";
    if (raw.length === 1) return raw + "'";
    return raw.slice(0, -1) + '"' + raw.slice(-1);
}

/* חישוב ערך מספור התחלתי דינמי (כולל תמיכה בכרך ב') */
function formatPageNumberDisplay(pNum) {
    const pageNumPos = document.getElementById('page-num-position')?.value || 'bottom_center';
    const pageNumFormat = document.getElementById('page-num-format')?.value || 'gematria';
    const pageNumFrame = document.getElementById('page-num-frame')?.value || 'none';
    const startIdx = parseInt(document.getElementById('page-num-start-idx')?.value, 10) || 1;
    const initialValue = parseInt(document.getElementById('page-num-initial-value')?.value, 10) || 1;

    let displayPageNum = '';
    if (pageNumPos !== 'none' && pNum >= startIdx) {
        const effectiveNum = pNum - startIdx + initialValue;
        if (pageNumFormat === 'gematria') {
            displayPageNum = toGematria(effectiveNum);
        } else if (pageNumFormat === 'page_gematria') {
            displayPageNum = 'דף ' + toGematria(effectiveNum);
        } else if (pageNumFormat === 'numeric') {
            displayPageNum = String(effectiveNum);
        }
    }

    let framedPageNum = displayPageNum;
    if (displayPageNum && pageNumFrame !== 'none') {
        framedPageNum = `<span class="page-num-badge page-num-frame-${pageNumFrame}">${displayPageNum}</span>`;
    }

    return { displayPageNum, framedPageNum, pageNumPos };
}

/* ==========================================================================
   2. עדכון רשת, גופנים ומשתני CSS
   ========================================================================== */
function updateGrid() {
    const root = document.documentElement;
    const rawCol = parseFloat(document.getElementById('prop-col')?.value) || 40;
